import{_ as r,l,o as e,c as n,v as i,p as s,x as t,d,i as c,S as B}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"批量成交量分类","description":"","frontmatter":{"title":"批量成交量分类","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bulk-volume-classification.md","filePath":"quant/bulk-volume-classification.md","lastUpdated":1789023840000}'),p={name:"quant/bulk-volume-classification.md"};function m(h,a,u,V,P,E){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="批量成交量分类" tabindex="-1">批量成交量分类 <a class="header-anchor" href="#批量成交量分类" aria-label="Permalink to &quot;批量成交量分类&quot;">​</a></h1><div class="epigraph"><p>不必给每一笔成交贴买卖标签。把等体积的一桶看成一次实验，用桶内价格变化在正态里的位置，把整桶成交量拆成买的份额与卖的份额。</p><footer>—— Easley, López de Prado &amp; O&#39;Hara, Discerning Information from Trade Data, Journal of Financial Economics, 2016</footer></div><p><a href="/quant/lee-ready">Lee–Ready</a> 要逐笔对照报价，贵、吵、还依赖 BBO 对齐。<a href="/quant/vpin">VPIN</a> 需要的却是每个成交量桶里的买量与卖量，并不需要知道桶内第十七笔是谁主动。Easley、López de Prado 与 O&#39;Hara 把这件事收成 <strong>Bulk Volume Classification (BVC)</strong>：在<a href="/quant/volume-bars">成交量 bar</a>（或时间桶、金额桶）上，用标准化价格变化的正态 CDF 当买方成交量比例。本篇写 BVC 作为分类器本身——公式、σ 的估计、它与 tick 规则的系统偏差——而不把 VPIN 的毒性叙事再写一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逐笔方向在现代市场里有三层摩擦。隐藏单与中点匹配让成交价经常落在中点；多场所让对照报价与成交不对齐；数据量让逐笔匹配成为管道瓶颈。若问题只是「这一桶净买了多少」，逐笔错误还会在加总时部分对冲，但不保证无偏：中点错误率随活跃度变化，加总偏差是状态依赖的。需要一个不读报价、计算量为每桶一次、并且在成交加速时仍有定义的规则。</p><p>BVC 的赌注是：桶内买方份额与桶收益同向、且幅度可用一个单调函数（正态 CDF）来近似。它承认单笔方向不可知，只承认体积加权的倾向。问题是这个近似何时等于「真实主动买量比例」，何时只是把已实现波动改写成了买卖不平衡。</p><h3 id="正态-cdf-把涨跌映成份额" tabindex="-1">正态 CDF 把涨跌映成份额 <a class="header-anchor" href="#正态-cdf-把涨跌映成份额" aria-label="Permalink to &quot;正态 CDF 把涨跌映成份额&quot;">​</a></h3><p>对桶 \\(\\tau\\)，记开盘价 \\(P_{\\tau}^{o}\\)、收盘价 \\(P_{\\tau}^{c}\\)、桶体积 \\(V\\)（股数或合约数），\\(\\sigma\\) 为桶收益的滚动标准差。买方成交量</p> \\[V_\\tau^{B}=V\\cdot\\Phi\\bigl((P_{\\tau}^{c}-P_{\\tau}^{o})/\\sigma\\bigr),\\qquad V_\\tau^{S}=V-V_\\tau^{B}, \\]<p>\\(\\Phi\\) 为标准正态 CDF。收益为零时 \\(\\Phi(0)=1/2\\)，买卖对半。收益相对 \\(\\sigma\\) 很大时，几乎整桶标成单边。这与 tick 规则「每笔一个 ±1 再加总」不同：BVC 允许 0.62 这样的分数份额，不要求桶内每笔同向。</p><p><span class="marginnote">\\(\\sigma\\) 必须用<strong>已完成</strong>桶估计。若把当前桶的收益也喂进 \\(\\sigma\\)，分类与波动在同一点上互相定义，极端桶会被当成「正常波动」而份额向 1/2 收缩，或反过来被当成极端而份额顶格。滚动窗口应在封桶之后才更新。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先选时钟：等体积 \\(V\\) 最常见，也可用等金额或等日历间隔；原文强调成交量同步，因为信息事件伴随成交加速。封桶规则与 <a href="/quant/volume-bars">volume bars</a> 相同，跨桶成交要切开。封口后取首末价（或 VWAP 相对开盘，须预先锁定），标准化，过 \\(\\Phi\\)，得到 \\((V^B,V^S)\\)。输出可以是份额 \\(V^B/V\\)，也可以是不平衡 \\((V^B-V^S)/V=2\\Phi(z)-1\\)。</p><p>校准：在有官方主动标志的子样本上，把 BVC 份额对真实买量比例回归，看截距、斜率与 \\(R^2\\)。Easley 等人报告 BVC 与逐笔算法相比，在后续价格预测上不差甚至更好——那是<strong>预测标准</strong>，不是逐笔正确率。若你的任务是给每一笔贴标签，BVC 答非所问。若任务是毒性、冲击、买卖压力，应用桶级矩去评，不要用 Lee–Ready 的逐笔一致率去否决。</p><h3 id="正态只是一条方便的链接函数" tabindex="-1">正态只是一条方便的链接函数 <a class="header-anchor" href="#正态只是一条方便的链接函数" aria-label="Permalink to &quot;正态只是一条方便的链接函数&quot;">​</a></h3><p>\\(\\Phi\\) 可换成 logistic 或其他 S 形。形状决定「多大的标准化收益才把份额从 0.5 推到 0.9」。厚尾市场里正态把中等收益当成极端，份额过早顶格；若 \\(\\sigma\\) 被少数跳估得过大，份额又永远贴在 0.5。应报告 \\(\\Phi(z)\\) 的经验直方图：若大量质量贴在 0 与 1，分类器退化成「涨即全买、跌即全卖」，与符号函数无异。此时要么加大 \\(V\\) 让单桶更接近扩散，要么换链接函数，而不是继续宣称分数份额的精细。</p>',16)),(e(),s(B,null,{default:t(()=>[c(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E6%88%90%E4%BA%A4%E6%B5%81%22%5D%20--%3E%20BAR%5B%22%E7%B4%AF%E5%8A%A0%E8%87%B3%E4%BD%93%E7%A7%AF%20V%20%E5%B0%81%E6%A1%B6%22%5D%0A%20%20BAR%20--%3E%20DP%5B%22%E6%A1%B6%E5%86%85%20%CE%94P%22%5D%0A%20%20SIG%5B%22%E5%B7%B2%E5%AE%8C%E6%88%90%E6%A1%B6%E7%9A%84%20%CF%83%22%5D%20--%3E%20Z%5B%22z%20%3D%20%CE%94P%20%2F%20%CF%83%22%5D%0A%20%20DP%20--%3E%20Z%0A%20%20Z%20--%3E%20PHI%5B%22%CE%A6(z)%20%3D%20%E4%B9%B0%E6%96%B9%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20PHI%20--%3E%20VS%5B%22V%5EB%2C%20V%5ES%22%5D%0A%20%20VS%20--%3E%20USE%5B%22VPIN%20%2F%20%E4%B8%8D%E5%B9%B3%E8%A1%A1%20%2F%20%E5%86%B2%E5%87%BB%E5%9B%9E%E5%BD%92%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制叙事是：知情交易在短窗里留下同向成交与价格移动，买方份额应随 \\(\\Delta P\\) 上升。噪声交易与存货在桶内对冲，净 \\(\\Delta P\\) 小，份额接近一半。BVC 把这条叙事参数化成一个正态概率，而不是逐笔贝叶斯。它与 Glosten–Milgrom 的「方向更新信念」同族，但观测从单笔换成了桶统计量。</p><p>竞争性机制不需要知情者。波动上升时 \\(|\\Delta P|/\\sigma\\) 的分布若未被 \\(\\sigma\\) 及时跟上，份额会两极化，不平衡看起来像毒性，其实是波动。这正是 Andersen、Bondarenko 对 VPIN 的质疑在分类器层面的根源：BVC 的输入是价格变化，输出却被叫做订单流。任何用 BVC 不平衡去「预测」后续波动的检验，都有一部分是用过去 \\(\\Delta P\\) 预测未来 \\(|\\Delta P|\\)。干净的做法是：在同一成交量时钟上并排已实现波动，看不平衡的增量解释力。</p><h3 id="与-tick-规则加总不是同一极限" tabindex="-1">与 tick 规则加总不是同一极限 <a class="header-anchor" href="#与-tick-规则加总不是同一极限" aria-label="Permalink to &quot;与 tick 规则加总不是同一极限&quot;">​</a></h3><p>把桶内每笔用 tick 规则分类再加总，得到整数买量。BVC 得到分数。当 \\(V\\to\\) 单笔，\\(\\Phi(\\Delta P/\\sigma)\\) 仍不是 tick 规则：单笔 \\(\\Delta P\\) 是相对桶开盘，不是相对上一成交，且 \\(\\sigma\\) 是桶级。两种分类器在 \\(V=1\\) 时也不收敛到对方。因此「BVC 是 tick 规则的平滑」是错的。BVC 是价格变化的链接函数，tick 规则是成交价路径的符号序列。</p><p><span class="marginnote">金额桶与股数桶给出不同的 \\(z\\)。高价股一笔金额大，等金额桶更短；低价股相反。跨股票比较 BVC 份额前，必须锁定体积单位，否则比较的是采样频率，不是信息。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>开盘集合竞价、涨跌停、停牌复牌：\\(\\Delta P\\) 受制度截断，\\(\\Phi\\) 失真，这些桶应丢弃或改用 tick 规则。多市场把同一套利腿记进两个桶，BVC 会把对冲交易读成双倍单边。\\(\\sigma\\) 窗口太短，分类抖动；太长，体制切换后份额迟迟不极化。不要用闪崩单日去标定 \\(V\\) 与 \\(\\sigma\\) 窗再声称样本外有效。</p><p>不要把 BVC 份额叫做 PIN。不要在没有封桶纪律的日历五分钟线上贴 BVC 标签却声称成交量同步。不要用逐笔 Lee–Ready 正确率作为 BVC 的验收标准。生产上：主序列可以是 BVC，对照序列用官方主动标志在同一桶内加总；只有任务真正需要逐笔 \\(D\\) 时才回到报价规则。</p><p><span class="marginnote">出处：Easley, López de Prado &amp; O&#39;Hara, <em>Discerning Information from Trade Data</em>, Journal of Financial Economics, 2016。VPIN 对 BVC 的使用见同一作者 RFS 2012。质疑见 Andersen 与 Bondarenko 对价格变化进入订单流度量的讨论。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BVC 用桶内标准化价格变化的 CDF 把整桶体积拆成买卖份额，不读报价、不逐笔贴标签。</li><li>\\(\\sigma\\) 只用已完成桶；否则分类与波动互相定义。</li><li>评价应在桶级预测与不平衡矩上做，不要用逐笔正确率否决。</li><li>输出与价格变化共享信息，和后续波动的相关一部分是机械的。</li><li>它不是 tick 规则的平滑极限，也不是 PIN。</li><li>制度截断与跨市场重复计算会让 \\(\\Phi\\) 失真。</li><li>出处：Easley, López de Prado &amp; O&#39;Hara, Journal of Financial Economics, 2016。</li></ul>',12))])}const D=r(p,[["render",m]]);export{f as __pageData,D as default};
